using Htt.Infrastructure;
using Htt.SharedKernel;
using Htt.Host.Api.MasterData;
using Htt.Host.Api.Sales;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.Inventory;
public sealed record BinUpdateInput(string Name,bool Active);
public sealed record BinInput(Guid WarehouseId,string Code,string Name);
public sealed record PositionMoveInput(Guid SourcePositionId,Guid TargetBinId,string LotCode,decimal BaseQuantity,string Reference,string Reason,Guid? CountId=null);
public sealed record ShortPickReasonInput(Guid OrderLineId,string Reason);
internal static class WarehouseDetailEndpoints
{
    public static void Map(RouteGroupBuilder g)
    {
        g.MapGet("/warehouse/bins",async(Guid warehouseId,CompanySession s,CancellationToken ct)=>{await Scope(s,warehouseId,false,ct);return Results.Ok(new{items=(await Read(s,"SELECT id,warehouse_id,code,name,active,version,'BIN:'||id::text AS scan_value FROM inventory.bins WHERE company_id=@company AND warehouse_id=@warehouse ORDER BY code,id",ct,new DbArg("warehouse",warehouseId))).Select(PublicRow)});}).WithMetadata(new Permission("inventory.locations.read"));
        g.MapPost("/warehouse/bins",async(BinInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>
        {
            await Scope(s,input.WarehouseId,true,ct);var code=Check.Code(input.Code);Check.That(code!="UNASSIGNED","code","UNASSIGNED is managed automatically.");var name=Check.Text(input.Name,"name");var result=await idem.ExecuteAsync("POST /warehouse/bins",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{input.WarehouseId,code,name}),async()=>{var row=await One(s,"INSERT INTO inventory.bins(company_id,warehouse_id,code,name) VALUES(@company,@warehouse,@code,@name) RETURNING *",ct,new DbArg("warehouse",input.WarehouseId),new DbArg("code",code),new DbArg("name",name));await Sql.AuditAsync(s,"inventory.bin_created","warehouse_bin",(Guid)row["id"]!,h.TraceIdentifier,ct,new{input.WarehouseId,code,name});return ApiJson.Stored(PublicRow(row));},ct);return ApiJson.Result(result);
        }).WithMetadata(new Permission("inventory.locations.write"));
        g.MapPut("/warehouse/bins/{id:guid}",async(Guid id,BinUpdateInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>
        {
            var before=await One(s,"SELECT warehouse_id FROM inventory.bins WHERE company_id=@company AND id=@id",ct,new DbArg("id",id));await Scope(s,(Guid)before["warehouse_id"]!,true,ct);if(!long.TryParse(h.Request.Headers.IfMatch.ToString().Trim('"'),out var version)||version<1)throw new BusinessException("version_required","Current If-Match required.",428);var name=Check.Text(input.Name,"name",200);var result=await idem.ExecuteAsync($"PUT /warehouse/bins/{id}",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,version,name,input.Active}),async()=>{await Read(s,"SELECT inventory.configure_bin(@id,@version,@name,@active)",ct,new DbArg("id",id),new DbArg("version",version),new DbArg("name",name),new DbArg("active",input.Active));await Sql.AuditAsync(s,"inventory.bin_changed","warehouse_bin",id,h.TraceIdentifier,ct,new{name,input.Active});return ApiJson.Stored(PublicRow(await One(s,"SELECT * FROM inventory.bins WHERE company_id=@company AND id=@id",ct,new DbArg("id",id))),200);},ct);return ApiJson.Result(result);
        }).WithMetadata(new Permission("inventory.locations.write"));
        g.MapGet("/warehouse/positions",Positions).WithMetadata(new Permission("inventory.locations.read"));
        g.MapPost("/warehouse/location-moves",async(PositionMoveInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>
        {
            var row=await One(s,"SELECT b.warehouse_id FROM inventory.positions p JOIN inventory.stock_balances b ON b.company_id=p.company_id AND b.id=p.stock_balance_id WHERE p.company_id=@company AND p.id=@id",ct,new DbArg("id",input.SourcePositionId));await Scope(s,(Guid)row["warehouse_id"]!,true,ct);Check.Amount(input.BaseQuantity,"baseQuantity",6);Check.That(input.BaseQuantity>0,"baseQuantity","Positive base quantity required.");var lot=Check.Text(input.LotCode,"lotCode",80);var reference=Check.Text(input.Reference,"reference",200);var reason=Check.Text(input.Reason,"reason",2000);var result=await idem.ExecuteAsync("POST /warehouse/location-moves",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{input.SourcePositionId,input.TargetBinId,input.BaseQuantity,lot,reference,reason,input.CountId}),async()=>{var doc=(Guid)(await One(s,"SELECT inventory.move_position(@source,@bin,@lot,@qty,@reference,@reason,@count) AS id",ct,new DbArg("source",input.SourcePositionId),new DbArg("bin",input.TargetBinId),new DbArg("lot",lot),new DbArg("qty",input.BaseQuantity),new DbArg("reference",reference),new DbArg("reason",reason),new DbArg("count",input.CountId,NpgsqlDbType.Uuid)))["id"]!;await Sql.AuditAsync(s,"inventory.location_moved","location_move",doc,h.TraceIdentifier,ct,new{input.SourcePositionId,input.TargetBinId,input.BaseQuantity,lot,reference,reason,input.CountId});return ApiJson.Stored(PublicRow(await One(s,"SELECT m.*,d.number FROM inventory.location_moves m JOIN platform.documents d ON d.company_id=m.company_id AND d.id=m.id WHERE m.company_id=@company AND m.id=@id",ct,new DbArg("id",doc))));},ct);return ApiJson.Result(result);
        }).WithMetadata(new Permission("inventory.locations.write"));
        g.MapGet("/warehouse/lot-trace",async(Guid warehouseId,Guid lotId,int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{await Scope(s,warehouseId,false,ct);var(offset,size)=Page(page,pageSize);var rows=await Read(s,"SELECT m.id,m.document_id,m.quantity,m.reason,m.request_id,m.created_at,bn.code AS bin_code,l.code AS lot_code,b.product_id FROM inventory.position_movements m JOIN inventory.positions p ON p.company_id=m.company_id AND p.id=m.position_id JOIN inventory.stock_balances b ON b.company_id=p.company_id AND b.id=p.stock_balance_id JOIN inventory.bins bn ON bn.company_id=p.company_id AND bn.id=p.bin_id JOIN inventory.lots l ON l.company_id=p.company_id AND l.id=p.lot_id WHERE m.company_id=@company AND b.warehouse_id=@warehouse AND p.lot_id=@lot ORDER BY m.created_at,m.id LIMIT @size OFFSET @offset",ct,new DbArg("warehouse",warehouseId),new DbArg("lot",lotId),new DbArg("size",size),new DbArg("offset",offset));return Results.Ok(new{items=rows.Select(PublicRow),page=page??1,pageSize=size});}).WithMetadata(new Permission("inventory.locations.read"));
        g.MapGet("/warehouse/scan",Scan).WithMetadata(new Permission("inventory.locations.read"));
        g.MapPost("/warehouse/picks/{id:guid}/short-pick-reasons",async(Guid id,ShortPickReasonInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>
        {
            var p=await One(s,"SELECT p.order_id,o.warehouse_id FROM inventory.picks p JOIN sales.orders o ON o.company_id=p.company_id AND o.id=p.order_id WHERE p.company_id=@company AND p.id=@id",ct,new DbArg("id",id));await Read(s,"SELECT inventory.require_access('inventory.picks.write',@warehouse)",ct,new DbArg("warehouse",p["warehouse_id"]));var reason=Check.Text(input.Reason,"reason",500);var result=await idem.ExecuteAsync($"POST /warehouse/picks/{id}/short-pick-reasons",h.Request.Headers["Idempotency-Key"].ToString(),Json(new{id,input.OrderLineId,reason}),async()=>{var line=await One(s,"SELECT l.quantity-coalesce((SELECT sum(pl.quantity) FROM inventory.pick_lines pl JOIN inventory.picks pk ON pk.company_id=pl.company_id AND pk.id=pl.pick_id WHERE pl.company_id=l.company_id AND pl.order_line_id=l.id AND pk.state IN('PICKED','DISPATCHED')),0) AS missing FROM sales.order_lines l WHERE l.company_id=@company AND l.order_id=@order AND l.id=@line FOR UPDATE",ct,new DbArg("order",p["order_id"]),new DbArg("line",input.OrderLineId));Check.That((decimal)line["missing"]!>0,"orderLineId","No shortage remains on this order line.");var row=await One(s,"INSERT INTO inventory.pick_shortages(company_id,pick_id,order_line_id,missing_quantity,reason,created_by) VALUES(@company,@id,@line,@missing,@reason,@actor) RETURNING *",ct,new DbArg("id",id),new DbArg("line",input.OrderLineId),new DbArg("missing",line["missing"]),new DbArg("reason",reason));await Sql.AuditAsync(s,"inventory.short_pick_recorded","pick_shortage",(Guid)row["id"]!,h.TraceIdentifier,ct,new{pickId=id,input.OrderLineId,reason});return ApiJson.Stored(PublicRow(row));},ct);return ApiJson.Result(result);
        }).WithMetadata(new Permission("inventory.picks.write"));
    }
    private static Task<List<Dictionary<string,object?>>> Scope(CompanySession s,Guid wh,bool write,CancellationToken ct)=>Read(s,"SELECT inventory.require_access(@permission,@warehouse)",ct,new DbArg("permission",write?"inventory.locations.write":"inventory.locations.read"),new DbArg("warehouse",wh));
    private static async Task<IResult> Positions(Guid warehouseId,Guid? productId,Guid? binId,Guid? lotId,int? page,int? pageSize,CompanySession s,CancellationToken ct)
    {
        await Scope(s,warehouseId,false,ct);var(offset,size)=Page(page,pageSize);var rows=await Read(s,"SELECT p.id,b.product_id,pr.sku,p.bin_id,bn.code AS bin_code,bn.active AS bin_active,p.lot_id,l.code AS lot_code,l.received_on,p.quantity,inventory.position_reserved(p.id) AS picked_reserved,p.quantity-inventory.position_reserved(p.id) AS available_for_pick,p.version FROM inventory.positions p JOIN inventory.stock_balances b ON b.company_id=p.company_id AND b.id=p.stock_balance_id JOIN catalog.products pr ON pr.company_id=b.company_id AND pr.id=b.product_id JOIN inventory.bins bn ON bn.company_id=p.company_id AND bn.id=p.bin_id JOIN inventory.lots l ON l.company_id=p.company_id AND l.id=p.lot_id WHERE p.company_id=@company AND b.warehouse_id=@warehouse AND (@product IS NULL OR b.product_id=@product) AND (@bin IS NULL OR p.bin_id=@bin) AND (@lot IS NULL OR p.lot_id=@lot) ORDER BY pr.sku,bn.code,l.received_on,p.id LIMIT @size OFFSET @offset",ct,new DbArg("warehouse",warehouseId),new DbArg("product",productId,NpgsqlDbType.Uuid),new DbArg("bin",binId,NpgsqlDbType.Uuid),new DbArg("lot",lotId,NpgsqlDbType.Uuid),new DbArg("size",size),new DbArg("offset",offset));return Results.Ok(new{items=rows.Select(PublicRow),page=page??1,pageSize=size});
    }
    private static async Task<IResult> Scan(Guid warehouseId,string code,CompanySession s,CancellationToken ct)
    {
        await Scope(s,warehouseId,false,ct);var token=Check.Text(code,"code",100);
        if(token.StartsWith("BIN:",StringComparison.Ordinal)&&Guid.TryParse(token[4..],out var bin))return Results.Ok(new{kind="BIN",item=PublicRow(await One(s,"SELECT id,code,name,active FROM inventory.bins WHERE company_id=@company AND warehouse_id=@warehouse AND id=@id",ct,new DbArg("warehouse",warehouseId),new DbArg("id",bin)))});
        if(token.StartsWith("LOT:",StringComparison.Ordinal)&&Guid.TryParse(token[4..],out var lot))return Results.Ok(new{kind="LOT",items=(await Read(s,"SELECT p.id,p.quantity,b.product_id,p.bin_id,p.lot_id FROM inventory.positions p JOIN inventory.stock_balances b ON b.company_id=p.company_id AND b.id=p.stock_balance_id WHERE p.company_id=@company AND b.warehouse_id=@warehouse AND p.lot_id=@lot ORDER BY p.id",ct,new DbArg("warehouse",warehouseId),new DbArg("lot",lot))).Select(PublicRow)});
        var rows=await Read(s,"SELECT p.id AS product_id,p.sku,p.name,p.status,p.item_type,u.id AS product_unit_id,u.conversion_to_base,u.quantity_step,u.active AS unit_active FROM catalog.products p JOIN catalog.product_units u ON u.company_id=p.company_id AND u.product_id=p.id WHERE p.company_id=@company AND(EXISTS(SELECT 1 FROM catalog.unit_barcodes bc WHERE bc.company_id=u.company_id AND bc.product_unit_id=u.id AND bc.active AND bc.barcode=@code) OR(u.uom_id=p.base_uom_id AND(p.sku=@code OR EXISTS(SELECT 1 FROM catalog.product_barcodes bc WHERE bc.company_id=p.company_id AND bc.product_id=p.id AND bc.barcode=@code)))) ORDER BY p.sku,u.id",ct,new DbArg("code",token));if(rows.Count==0)throw new BusinessException("not_found","Barcode/SKU is unavailable.",404);return Results.Ok(new{kind="PRODUCT",items=rows.Select(PublicRow)});
    }
}
